<script setup>
import {ref,reactive,onActivated} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {http,allRows} from '../api/http'
import {download} from '../api/download'
import {auth} from '../stores/auth'
import {useDirty} from '../stores/dirty'
const personal=auth.user?.role==='EMPLOYEE',rows=ref([]),total=ref(0),busy=ref(false),dialog=ref(false),editing=ref(null),departments=ref([])
const today=new Date(),month=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`
const filter=reactive({month,keyword:'',department_id:null,page:1,page_size:10}),form=reactive({bonus:'0.00',deduction:'0.00'})
const resetDirty=useDirty(()=>form,()=>dialog.value)
async function load(){busy.value=true;try{const r=await http.get(personal?'/employee/payroll':'/payroll',{params:filter});rows.value=r.data;total.value=r.total;if(!personal)departments.value=await allRows('/departments')}catch{}finally{busy.value=false}}
async function generate(){try{await ElMessageBox.confirm(`生成${filter.month}工资草稿？已有记录不会被覆盖。`,'生成确认')}catch{return}try{const r=await http.post('/payroll/generate',{salary_month:filter.month});ElMessage.success(`新增${r.data.created}条工资草稿`);load()}catch{}}
async function save(){try{await http.patch('/payroll/'+editing.value.id,form);dialog.value=false;resetDirty();ElMessage.success('工资已保存');load()}catch{}}
async function status(row,kind){try{await ElMessageBox.confirm(kind==='mark-paid'?'确认标记已发放？标记后将不能直接编辑。':'确认撤回发放状态？','工资状态确认',{type:'warning'})}catch{return}try{await http.post(`/payroll/${row.id}/${kind}`);ElMessage.success('状态已更新');load()}catch{}}
onActivated(load)
</script>
<template><div class="page-title"><div><h1>{{personal?'我的工资':'薪资管理'}}</h1><p>实发工资 = 基本工资快照 + 奖金 − 扣款，金额由后端精确计算。</p></div><div v-if="!personal"><el-button @click="download('/payroll/export',filter,'月度工资')">导出 Excel</el-button><el-button type="primary" @click="generate">生成工资草稿</el-button></div></div><el-card shadow="never"><el-form inline class="filters"><el-form-item label="月份"><el-date-picker v-model="filter.month" type="month" value-format="YYYY-MM" :clearable="false"/></el-form-item><el-form-item v-if="!personal" label="姓名"><el-input v-model="filter.keyword"/></el-form-item><el-form-item v-if="!personal" label="部门"><el-select v-model="filter.department_id" clearable><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-button @click="filter.page=1;load()">查询</el-button><el-button @click="Object.assign(filter,{month,keyword:'',department_id:null,page:1});load()">重置</el-button></el-form><el-table v-loading="busy" :data="rows" empty-text="本月暂无工资记录"><el-table-column prop="employee_code" label="员工编号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="salary_month" label="月份"/><el-table-column prop="base_salary" label="基本工资（元）"/><el-table-column prop="bonus" label="奖金"/><el-table-column prop="deduction" label="扣款"/><el-table-column prop="net_salary" label="实发工资"/><el-table-column label="发放状态"><template #default="{row}">{{row.status==='paid'?'已发放':'未发放'}}</template></el-table-column><el-table-column v-if="!personal" label="操作" width="180"><template #default="{row}"><template v-if="row.status==='unpaid'"><el-button link type="primary" @click="editing=row;Object.assign(form,{bonus:row.bonus,deduction:row.deduction});dialog=true">编辑</el-button><el-button link type="success" @click="status(row,'mark-paid')">标记已发放</el-button></template><el-button v-else link type="warning" @click="status(row,'reopen')">撤回发放</el-button></template></el-table-column></el-table><el-pagination class="pagination" v-model:current-page="filter.page" :page-size="10" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><WorkspaceDialog v-model="dialog" title="编辑工资" width="460px"><el-form label-position="top"><el-form-item label="奖金（元）" required><el-input v-model="form.bonus"/></el-form-item><el-form-item label="扣款（元）" required><el-input v-model="form.deduction"/></el-form-item><el-button type="primary" @click="save">保存工资</el-button></el-form></WorkspaceDialog></template>
